// aggregates attribute the row to). Money columns stay NUMERIC(14,2).
func (q *Queries) ListCrmClients(ctx context.Context, arg ListCrmClientsParams) ([]CrmClient, error) {
	rows, err := q.db.Query(ctx, listCrmClients,
		arg.WorkspaceID,
		arg.Query,
		arg.CursorAt,
		arg.CursorID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CrmClient{}
	for rows.Next() {
		var i CrmClient
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Name,
			&i.Brand,
			&i.Industry,
			&i.ContactName,
			&i.ContactChannel,
			&i.ContractEntity,
			&i.PaymentTerms,
			&i.CreditNote,
			&i.OwnerMemberID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

